nextflow_process {

    name "Test Process DIANN"
    script "../main.nf"
    process "DIANN"

    tag "modules"
    tag "modules_nfcore"
    tag "diann"

    test("proteomics - in-silico library generation") {
        config "./nextflow.config"

        when {
            process {
                """
                input[0] = channel.of([
                    [id:'ecoli_test', config: '--cut K*,R*,!*P --fixed-mod Carbamidomethyl,57.021464,C --var-mod Oxidation,15.994915,M'],
                    [], // ms_files
                    [], // ms_file_names
                    file(params.modules_testdata_base_path + 'proteomics/diann/REF_EColi_K12_UPS1_combined_subset_100.fasta', checkIfExists: true),
                    [], // library
                    []  // quant
                ])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path("${process.out.log[0][1]}").exists() },
                { assert path("${process.out.predict_speclib[0][1]}").exists() },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("proteomics - preliminary analysis") {
        config "./nextflow_preliminaryanalysis.config"
        def mzml_dir
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            mzml_dir = extract(modules_testdata_base_path + 'proteomics/diann/RD139_Narrow_UPS1_0_1fmol_inj1.mzML.tar.gz')
        }

        when {
            process {
                """
                input[0] = [[id:'test'], file('${mzml_dir}/RD139_Narrow_UPS1_0_1fmol_inj1.mzML'), [], [], file(params.modules_testdata_base_path + 'proteomics/diann/lib.predicted.speclib', checkIfExists: true), []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path("${process.out.log[0][1]}").exists() },
                { assert snapshot(
                    process.out.diann_quant,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("proteomics - assemble empirical library") {
        config "./nextflow_assembleempiricallibrary.config"
        def mzml_dir
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            mzml_dir = extract(modules_testdata_base_path + 'proteomics/diann/RD139_Narrow_UPS1_0_1fmol_inj1.mzML.tar.gz')
        }

        when {
            process {
                """
                input[0] = [[id:'test_exp'], [file('${mzml_dir}/RD139_Narrow_UPS1_0_1fmol_inj1.mzML')], [], [], file(params.modules_testdata_base_path + 'proteomics/diann/lib.predicted.speclib', checkIfExists: true), [file(params.modules_testdata_base_path + 'proteomics/diann/preliminary_analysis.quant', checkIfExists: true)]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path("${process.out.log[0][1]}").exists() },
                { assert path("${process.out.final_speclib[0][1]}").exists() },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("proteomics - individual analysis") {
        config "./nextflow_individualanalysis.config"
        def mzml_dir
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            mzml_dir = extract(modules_testdata_base_path + 'proteomics/diann/RD139_Narrow_UPS1_0_1fmol_inj1.mzML.tar.gz')
        }

        when {
            process {
                """
                input[0] = [[id:'test'], file('${mzml_dir}/RD139_Narrow_UPS1_0_1fmol_inj1.mzML'), [], file(params.modules_testdata_base_path + 'proteomics/diann/REF_EColi_K12_UPS1_combined_subset_100.fasta', checkIfExists: true), file(params.modules_testdata_base_path + 'proteomics/diann/empirical_library.speclib', checkIfExists: true), []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path("${process.out.log[0][1]}").exists() },
                { assert snapshot(
                    process.out.diann_quant,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("proteomics - final quantification") {
        config "./nextflow_finalquantification.config"

        when {
            process {
                """
                input[0] = channel.of([
                    [id:'test_exp'],
                    [], // ms_files (not used in final quant)
                    ['RD139_Narrow_UPS1_0_1fmol_inj1.mzML'], // ms_file_names (basenames for --use-quant)
                    file(params.modules_testdata_base_path + 'proteomics/diann/REF_EColi_K12_UPS1_combined_subset_100.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'proteomics/diann/empirical_library.speclib', checkIfExists: true),
                    [file(params.modules_testdata_base_path + 'proteomics/diann/individual_analysis.quant', checkIfExists: true)]
                ])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path("${process.out.log[0][1]}").exists() },
                { assert snapshot(
                    process.out.report_stats,
                    process.out.pr_matrix,
                    process.out.pg_matrix,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }
}

