// Configuration for in-silico library generation mode
// Matches the subworkflow DIANN_INSILICOLIBRARYGENERATION configuration
process {
    withName: 'DIANN' {
        ext.args = {[
            meta.config ?: '',
            '--min-pr-mz 350',
            '--max-pr-mz 950',
            '--min-fr-mz 500',
            '--max-fr-mz 1500',
            '--missed-cleavages 1',
            '--min-pep-len 15',
            '--max-pep-len 30',
            '--min-pr-charge 2',
            '--max-pr-charge 3',
            '--var-mods 2',
            '--verbose 3',
            '--fasta-search',
            '--predictor',
            '--gen-spec-lib',
            '--met-excision'
        ].join(' ').trim()}
    }
}

// Configuration for assemble empirical library mode
// Matches the subworkflow DIANN_ASSEMBLEEMPIRICALLIBRARY configuration
process {
    withName: 'DIANN' {
        ext.prefix = 'empirical_library'
        ext.args = '--verbose 3 --rt-profiling --use-quant --gen-spec-lib --individual-mass-acc --individual-windows'
    }
}

// Configuration for final quantification mode
// Matches the subworkflow DIANN_FINALQUANTIFICATION configuration
// Note: Includes --matrix-qvalue 1 which is test-specific (not in base subworkflow config)
process {
    withName: 'DIANN' {
        ext.prefix = 'diann_report'
        ext.args = '--verbose 3 --relaxed-prot-inf --pg-level 1 --use-quant --matrices --qvalue 1.0 --matrix-qvalue 1 --individual-windows'
    }
}

// Configuration for individual analysis mode
// Matches the subworkflow DIANN_INDIVIDUALANALYSIS configuration
// Note: Hardcodes mass accuracy values that would normally come from meta (meta.mass_acc_ms2, meta.mass_acc_ms1, meta.scan_window)
process {
    withName: 'DIANN' {
        ext.args = '--verbose 3 --no-ifs-removal --no-main-report --relaxed-prot-inf --pg-level 1 --mass-acc 20 --mass-acc-ms1 20 --window 20'
    }
}

// Configuration for preliminary analysis mode
// Matches the subworkflow DIANN_PRELIMINARYANALYSIS configuration
process {
    withName: 'DIANN' {
        ext.args = '--verbose 3 --quick-mass-acc --min-corr 2 --corr-diff 1 --time-corr-only'
    }
}
